  --voice-transcription-line-height: 1.5;
}

.msg-plain-me:has(.voice-msg), .msg-plain-them:has(.voice-msg) { padding: 7px 12px !important; }
.voice-msg { width: fit-content !important; min-width: 0 !important; max-width: 100% !important; }

.voice-transcription-toggle {
  position: absolute !important;
  top: 0 !important; right: 0 !important; bottom: 0 !important; left: 0 !important;
  width: auto !important; height: auto !important;
  margin: 0 !important; padding: 0 !important;
  opacity: 0 !important; font-size: 0 !important;
  z-index: 1 !important; cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.voice-play-btn, .voice-download-btn { position: relative !important; z-index: 3 !important; }
.voice-transcription { border: none !important; border-top: 1px dashed var(--quote-dash) !important; box-shadow: none !important; }

/* =====================================================
   引用消息
   ===================================================== */
:root {
  --quote-gray: #aaa3a6;                          
  --quote-dash: #cfc8cb;                          
  --quote-line-bottom: 1px dashed var(--quote-dash);  
  --quote-line-left: none;                        
  --quote-pad-left: 0px;
  --reply-block-bg: transparent;
  --reply-block-radius: 0;
  --reply-block-border: none;
  --reply-block-border-left: none;
  --reply-block-name-color: var(--quote-gray);
  --reply-block-text-color: var(--quote-gray);
}

.msg-reply-block {
  background: transparent !important; border: none !important;
  border-bottom: var(--quote-line-bottom) !important; border-left: var(--quote-line-left) !important;
  border-radius: 0 !important; box-shadow: none !important;
  padding: 0 0 7px var(--quote-pad-left) !important; margin: 0 0 7px !important;
}
.msg-reply-block-name { color: var(--quote-gray) !important; font-size: 11px !important; }
.msg-reply-block-text, .msg-reply-block-media { color: var(--quote-gray) !important; font-size: 12px !important; }

.msg-plain-me.plain-first:has(.msg-reply-block)::after, .msg-plain-me.plain-single:has(.msg-reply-block)::after,
.msg-plain-them.plain-first:has(.msg-reply-block)::after, .msg-plain-them.plain-single:has(.msg-reply-block)::after { content: none !important; }
.msg-plain-me.plain-first:has(.msg-reply-block), .msg-plain-me.plain-single:has(.msg-reply-block) { border-top-right-radius: var(--bubble-round) !important; }
.msg-plain-them.plain-first:has(.msg-reply-block), .msg-plain-them.plain-single:has(.msg-reply-block) { border-top-left-radius: var(--bubble-round) !important; }

